class ScriptedGithubMergeGate implements GithubMergeGatePort {
  readonly checks: Array<{ repo: string; number: number; expectedHeadSha?: string }> = []
  readonly merges: GithubMergeInput[] = []
  readonly #verdicts: GithubMergeGateVerdict[]
  #mergeResult: { merged: boolean; reason: string }

  constructor(verdicts: GithubMergeGateVerdict[], mergeResult: { merged: boolean; reason: string } = { merged: true, reason: 'merged' }) {
    this.#verdicts = [...verdicts]
    this.#mergeResult = mergeResult
  }

  async check(input: { repo: string; number: number; expectedHeadSha?: string }): Promise<GithubMergeGateVerdict> {
    this.checks.push(input)
    return this.#verdicts.shift() ?? this.#verdicts.at(-1) ?? refusedMergeVerdict('no scripted verdict')
  }

  async merge(input: GithubMergeInput): Promise<{ merged: boolean; reason: string }> {
    this.merges.push(input)
    return this.#mergeResult
  }
}

class ScriptedVerificationGate implements VerificationGate {
  readonly inputs: VerificationGateInput[] = []

  constructor(readonly passed: boolean) {}

  async verify(input: VerificationGateInput): Promise<VerificationVerdict> {
    this.inputs.push(input)
    const stage = { status: this.passed ? 'pass' as const : 'fail' as const, durationMs: 1 }
    return {
      status: this.passed ? 'pass' : 'fail',
      passed: this.passed,
      reason: this.passed ? 'green fixture' : 'red fixture',
      evidence: {
        contract: 'factory.verification.evidence.v1',
        runId: 'verification-test',
        repository: input.repository,
        repositoryPath: input.repositoryPath,
        descriptorPath: `${input.repositoryPath}/.factory/verification-stack.yaml`,
        expectedHeadSha: input.expectedHeadSha,
        environmentId: 'factory-verify-test',
        namespace: 'factory-verify-test',
        startedAt: '2026-07-21T00:00:00.000Z',
        completedAt: '2026-07-21T00:00:01.000Z',
        timedOut: false,
        stages: {
          resolve: stage,
          provision: stage,
          deploy: stage,
          e2e: { ...stage, exitCode: this.passed ? 0 : 1 },
          load: stage,
          evaluate: stage,
          teardown: { status: 'pass', durationMs: 1 },
        },
      },
    }
  }
}

const readyMergeVerdict = (headRefOid = 'green-sha'): GithubMergeGateVerdict => ({
  verdict: 'READY',
  ready: true,
  reason: 'ready',
  live: {
    mergeable: 'MERGEABLE',
    mergeStateStatus: 'CLEAN',
    headRefOid,
    reviewDecision: 'APPROVED',
    checkStates: ['SUCCESS'],
  },
})

const refusedMergeVerdict = (reason: string): GithubMergeGateVerdict => ({
  verdict: 'REFUSE',
  ready: false,
  reason,
  live: {
    mergeable: 'MERGEABLE',
    mergeStateStatus: 'UNSTABLE',
    headRefOid: 'red-sha',
    reviewDecision: 'APPROVED',
    checkStates: ['FAILURE'],
  },
})

