class RosterPidHarnessClient implements HarnessDriverClientLike {
  readonly brokerPid = 68009
  readonly spawned: SpawnPtyInput[] = []
  readonly releases: Array<{ name: string; reason?: string }> = []
  readonly sent: SendMessageInput[] = []
  readonly inputs: Array<{ name: string; data: string }> = []
  readonly eventListeners = new Set<(event: BrokerEvent) => void>()
  readonly agents = new Map<string, { name: string; pid?: number }>()
  readonly pidsByName = new Map<string, number>()

  async spawnPty(input: SpawnPtyInput): Promise<{ name: string; session_ref: string }> {
    this.spawned.push(input)
    this.agents.set(input.name, { name: input.name })
    return { name: input.name, session_ref: `session-${input.name}` }
  }

  async release(name: string, reason?: string): Promise<{ name: string }> {
    this.releases.push({ name, reason })
    this.agents.delete(name)
    return { name }
  }

  async listAgents(): Promise<Array<{ name: string; pid?: number }>> {
    return [...this.agents.values()].map((agent) => ({ ...agent, pid: this.pidsByName.get(agent.name) }))
  }

  async sendMessage(input: SendMessageInput): Promise<{ event_id: string; targets?: string[] }> {
    this.sent.push(input)
    const eventId = `event-${this.sent.length}`
    this.emit({ kind: 'delivery_injected', event_id: eventId, name: input.to } as BrokerEvent)
    return { event_id: eventId, targets: [input.to] }
  }

  async sendInput(name: string, data: string): Promise<void> {
    this.inputs.push({ name, data })
  }

  connectEvents(): void {}

  onEvent(listener: (event: BrokerEvent) => void): () => void {
    this.eventListeners.add(listener)
    return () => {
      this.eventListeners.delete(listener)
    }
  }

  addListener(): () => void {
    return () => {}
  }

  emit(event: BrokerEvent): void {
    for (const listener of this.eventListeners) {
      listener(event)
    }
  }
}

class RegistrationLagBabysitterHarnessClient extends RosterPidHarnessClient {
  babysitterRelaycastLookups = 0
  failedFirstWake = false

  override async sendMessage(input: SendMessageInput): Promise<{ event_id: string; targets?: string[] }> {
    if (input.to.includes('-babysit') && input.text.startsWith('<integration-event')) {
      this.babysitterRelaycastLookups += 1
      if (!this.failedFirstWake) {
        this.failedFirstWake = true
        throw new Error(
          `Relaycast publish failed: relaycast send_dm failed: API error (agent_not_found): Agent "${input.to}" not found`,
        )
      }
    }
    return await super.sendMessage(input)
  }
}

// Every babysitter wake fails with the registration-lag (agent_not_found)
// signature and never recovers, modelling an agent that is up (local roster)
// but whose relay identity never becomes resolvable for cloud DMs.
class UnreachableBabysitterHarnessClient extends RosterPidHarnessClient {
  babysitterWakeAttempts = 0

  override async sendMessage(input: SendMessageInput): Promise<{ event_id: string; targets?: string[] }> {
    if (input.to.includes('-babysit') && input.text.startsWith('<integration-event')) {
      this.babysitterWakeAttempts += 1
      throw new Error(
        `Relaycast publish failed: relaycast send_dm failed: API error (agent_not_found): Agent "${input.to}" not found`,
      )
    }
    return await super.sendMessage(input)
  }
}

class RecoveringBabysitterHarnessClient extends RosterPidHarnessClient {
  babysitterWakeAttempts = 0
  resumed = false

  override async spawnPty(input: SpawnPtyInput): Promise<{ name: string; session_ref: string }> {
    const result = await super.spawnPty(input)
    if (input.continueFrom) this.resumed = true
    return result
  }

  override async sendMessage(input: SendMessageInput): Promise<{ event_id: string; targets?: string[] }> {
    if (input.to.includes('-babysit') && input.text.startsWith('<integration-event')) {
      this.babysitterWakeAttempts += 1
      if (!this.resumed) {
        throw new Error(
          `Relaycast publish failed: relaycast send_dm failed: API error (agent_not_found): Agent "${input.to}" not found`,
        )
      }
    }
    return await super.sendMessage(input)
  }
}

class ResumeThenColdStartBabysitterHarnessClient extends RosterPidHarnessClient {
  babysitterWakeAttempts = 0
  coldStarted = false
  recoverySpawnsUntilReachable = 0

  override async spawnPty(input: SpawnPtyInput): Promise<{ name: string; session_ref: string }> {
    const priorBabysitterSpawns = this.spawned.filter((spawn) => spawn.name.includes('-babysit')).length
    const result = await super.spawnPty(input)
    if (input.name.includes('-babysit') && priorBabysitterSpawns > 0 && !input.continueFrom) {
      this.coldStarted = true
    }
    if (input.name.includes('-babysit') && this.coldStarted && this.recoverySpawnsUntilReachable > 0) {
      this.recoverySpawnsUntilReachable -= 1
    }
    return result
  }

  override async sendMessage(input: SendMessageInput): Promise<{ event_id: string; targets?: string[] }> {
    if (input.to.includes('-babysit') && input.text.startsWith('<integration-event')) {
      this.babysitterWakeAttempts += 1
      if (!this.coldStarted || this.recoverySpawnsUntilReachable > 0) {
        throw new Error(
          `Relaycast publish failed: relaycast send_dm failed: API error (agent_not_found): Agent "${input.to}" not found`,
        )
      }
    }
    return await super.sendMessage(input)
  }
}

class CapabilityMigratingBabysitterHarnessClient extends RosterPidHarnessClient {
  babysitterWakeAttempts = 0

  override async sendMessage(input: SendMessageInput): Promise<{ event_id: string; targets?: string[] }> {
    if (input.to.includes('-babysit') && input.text.startsWith('<integration-event')) {
      this.babysitterWakeAttempts += 1
      const current = this.spawned.findLast((spawn) => spawn.name === input.to)
      if (current?.cli !== 'codex') {
        throw new Error(
          `Relaycast publish failed: relaycast send_dm failed: API error (agent_not_found): Agent "${input.to}" not found`,
        )
      }
    }
    return await super.sendMessage(input)
  }
}

class ResumeCollisionHarnessClient extends RosterPidHarnessClient {
  resumeAttempts = 0
  shutdownCalls = 0

  override async spawnPty(input: SpawnPtyInput): Promise<{ name: string; session_ref: string }> {
    if (input.continueFrom) {
      this.resumeAttempts += 1
      throw Object.assign(new Error(`agent '${input.name}' already exists`), {
        code: 'http_500',
        status: 500,
        retryable: true,
        data: { error: `agent '${input.name}' already exists`, name: input.name, success: false },
      })
    }
    return await super.spawnPty(input)
  }

  async shutdown(): Promise<void> {
    this.shutdownCalls += 1
  }
}

